    EnTextos.textMensajeTemporizaSal010Ventila,
    'Wenn dieser Ausgang zeitgesteuert ist, wird er zeitgesteuert, wenn er einem Lüfter zugeordnet ist, und der Lüfter wird auch zeitgesteuert, aber er wird nicht zeitgesteuert, wenn er einem statischen Lüfter zugeordnet ist. Es wird auch nicht zeitgesteuert, wenn es einer gemischten Kombination von zeitgesteuerten und statischen Lüftern auf derselben Bühne zugeordnet wird. Wenn die Einstellung nicht zeitgesteuert ist, wird dieser Ausgang in keinem Fall zeitgesteuert.'
