    'Der Import kann nach dem Start nicht abgebrochen werden. Schalten Sie den Computer nicht aus und trennen Sie den USB-Anschluss nicht, während der Import ausgeführt wird, da dies zu unerwünschten Vorgängen führen kann. Wenn der Import nicht abgeschlossen ist, müssen Sie ihn so bald wie möglich wiederholen.'
