    'Die Mindestzeit, die der Lüfter ausgeschaltet bleiben muss. Ist die Ausschaltzeit kürzer als dieser Parameter, wird der Lüfter nicht ausgeschaltet und arbeitet weiter. Dieser Parameter muss größer sein als der zeitliche Abstand der Lufteinlässe, bevor die Beatmung eingeleitet wird (Menü / Konfiguration / Depression / Erweitert).'
