    EnTextos.textMsjInfoVibradores,
    "Wenn der digitale Eingang des Silomotors aktiviert wird, beginnt die 'Überwachungszeit' zu zählen, wenn die 'Gewichtsänderung' in dieser Zeit nicht aufgetreten ist, wird das 'Vibratorrelais' für die 'Vibratorzeit' aktiviert. Nach Ablauf dieser Zeit wird der Vorgang wiederholt. Wenn alle Wiederholungen abgeschlossen sind, wird das „Silo-Stopp-Relais“ aktiviert und die Vibrationswarnung wird angezeigt. Um den Betrieb wieder aufzunehmen, müssen die Warnungen gelöscht werden."
